package com.argument.automation;

import com.argument.common.exception.*;
import com.argument.integration.UnifiedVersionIdentity;
import com.argument.version.*;
import com.argument.version.port.*;
import com.argument.version.port.VersionIdentity.Actor;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.time.Instant;
import java.util.*;
import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import static com.argument.adjudication.AdjudicationService.require;

@Service @Profile("(local | test) & !prod")
public class AutomationTaskService {
    public static final Set<String> STATES=Set.of("DRAFT","QUEUED","RUNNING","COMPLETED","FAILED","CANCELLED");
    private final AnnotationDependencies data;private final UnifiedVersionIdentity identities;private final VersionRepository versions;private final AutomationRepository store;private final ObjectMapper mapper;private final AutomationModelAdapter adapter;
    public AutomationTaskService(AnnotationDependencies data,UnifiedVersionIdentity identities,VersionRepository versions,AutomationRepository store,ObjectMapper mapper,AutomationModelAdapter adapter){this.data=data;this.identities=identities;this.versions=versions;this.store=store;this.mapper=mapper;this.adapter=adapter;}
    public Actor manager(Actor supplied){var actor=identities.actor(supplied.id());require(actor.role("TASK_CREATOR")&&actor.permission("AUTO_TASK_MANAGE"),ErrorCode.FORBIDDEN,"仅获授权任务创建者可管理自动任务");return actor;}
    private ObjectNode ownCase(Actor actor,String id){var doc=data.read("taskDocument",VersionJson.uuid(id));ownTask(actor,doc.path("taskId").asText());return doc;}
    private ObjectNode ownTask(Actor actor,String id){var task=data.read("task",VersionJson.uuid(id));require(actor.id().equals(task.path("ownerUserId").asText())&&data.find("member","taskId",id).stream().anyMatch(m->actor.id().equals(m.path("userId").asText())&&"OWNER".equals(m.path("memberRole").asText())&&"ACTIVE".equals(m.path("status").asText())),ErrorCode.FORBIDDEN,"只能管理本人作为有效 OWNER 的任务");return task;}
    private ObjectNode lockedCase(Actor actor,String id){data.lock("user",actor.id());manager(actor);ownCase(actor,id);versions.lockCase(id);var doc=data.lock("taskDocument",id);data.lock("task",doc.path("taskId").asText());ownCase(actor,id);return doc;}
    private void writable(ObjectNode doc){var task=data.read("task",doc.path("taskId").asText());require(Set.of("DRAFT","ASSIGNING","PUBLISHED","IN_PROGRESS").contains(task.path("status").asText())&&Set.of("PENDING_ASSIGNMENT","ANNOTATING","SEGMENTING").contains(doc.path("status").asText()),ErrorCode.LOCKED_RESOURCE,"任务或案例已锁定，不能继续自动预标注");}
    private void enabled(ObjectNode doc){require(data.read("task",doc.path("taskId").asText()).path("autoPreannotationEnabled").asBoolean(),ErrorCode.AUTO_DISABLED,"该任务未启用自动预标注");}
    private ObjectNode input(ObjectNode doc){var task=data.read("task",doc.path("taskId").asText());var text=data.read("text",doc.path("documentTextVersionId").asText());var scope=data.read("scope",doc.path("annotationScopeId").asText());var guide=data.read("guideVersion",task.path("guideVersionId").asText());String normalized=text.path("normalizedText").asText();int start=scope.path("startOffset").asInt(-1),end=scope.path("endOffset").asInt(-1);
        require(normalized.length()<=1_000_000&&"PUBLISHED".equals(text.path("status").asText())&&"CONFIRMED".equals(scope.path("status").asText())&&scope.path("documentTextVersionId").equals(text.path("id"))&&VersionJson.sha256(normalized).equals(text.path("contentSha256").asText())&&start>=0&&end>start&&end<=normalized.length()&&boundary(normalized,start)&&boundary(normalized,end),ErrorCode.SOURCE_INCOMPLETE,"固定文本、UTF-16 范围或摘要无效");
        require(Set.of("PUBLISHED","ARCHIVED").contains(guide.path("status").asText()),ErrorCode.GUIDE_NOT_READY,"绑定指南不可用于预标注");
        var input=mapper.createObjectNode();input.set("text",text);input.set("scope",scope);input.set("guideVersion",guide);input.set("model",adapter.descriptor());var labels=input.putArray("labels");boolean v12=Set.of("1.2","v1.2").contains(guide.path("versionCode").asText());data.find("label","guideVersionId",guide.path("id").asText()).stream().filter(l->!v12||!"GM-C".equals(l.path("code").asText())).sorted(Comparator.comparingInt((ObjectNode n)->n.path("sortOrder").asInt()).thenComparing(n->n.path("id").asText())).forEach(labels::add);var relations=input.putArray("relationDefinitions");data.find("relationDefinition","guideVersionId",guide.path("id").asText()).forEach(relations::add);require(labels.size()>0,ErrorCode.GUIDE_NOT_READY,"缺少指南字典");return input;
    }
    private boolean baseline(ObjectNode task){try{var doc=data.read("taskDocument",task.path("taskDocumentId").asText());return task.path("inputDigest").asText().equals(VersionJson.canonicalHash(input(doc)));}catch(BusinessException e){return false;}}
    private static boolean boundary(String text,int at){return at==0||at==text.length()||!Character.isHighSurrogate(text.charAt(at-1))||!Character.isLowSurrogate(text.charAt(at));}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public ObjectNode read(Actor supplied,String id){var actor=manager(supplied);var n=data.read("automationTask",VersionJson.uuid(id));ownCase(actor,n.path("taskDocumentId").asText());return n;}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public ObjectNode list(Actor supplied,String taskId,String status,int page,int size){var actor=manager(supplied);require(status==null||STATES.contains(status),ErrorCode.VALIDATION_ERROR,"未知自动任务状态");if(taskId!=null)ownTask(actor,taskId);var rows=new ArrayList<ObjectNode>();for(var n:data.find("automationTask",null,null)){try{var doc=ownCase(actor,n.path("taskDocumentId").asText());if((taskId==null||taskId.equals(doc.path("taskId").asText()))&&(status==null||status.equals(n.path("status").asText())))rows.add(n);}catch(BusinessException ex){if(ex.getErrorCode()!=ErrorCode.FORBIDDEN)throw ex;}}rows.sort(Comparator.comparing((ObjectNode n)->n.path("createdAt").asText()).reversed().thenComparing(n->n.path("id").asText()));var result=mapper.createObjectNode().put("total",rows.size());var items=result.putArray("items");rows.stream().skip((long)(page-1)*size).limit(size).forEach(items::add);return result;}
    @Transactional public ObjectNode create(Actor supplied,String caseId,String key,ObjectNode body){var actor=manager(supplied);fields(body,Set.of("modelId","modelVersion"));for(String f:List.of("modelId","modelVersion"))require(body.path(f).isTextual()&&!body.path(f).asText().isBlank()&&body.path(f).asText().length()<=100,ErrorCode.VALIDATION_ERROR,"模型身份和版本不能为空且最多 100 字符");VersionJson.uuid(key);var doc=lockedCase(actor,VersionJson.uuid(caseId));String operation="M02:"+caseId;var cached=replay(actor,operation,key,body);if(cached!=null)return cached;writable(doc);enabled(doc);var model=adapter.descriptor();require(body.path("modelId").equals(model.path("modelId"))&&body.path("modelVersion").equals(model.path("modelVersion"))&&model.path("available").asBoolean(),ErrorCode.VALIDATION_ERROR,"模型配置不存在或尚未接入执行服务");require(data.find("automationTask","taskDocumentId",caseId).stream().noneMatch(n->Set.of("DRAFT","QUEUED","RUNNING").contains(n.path("status").asText())),ErrorCode.CONFLICT,"本案例已有未结束自动任务，请先读取或取消");
        var frozen=input(doc);var n=mapper.createObjectNode();VersionJson.stamp(n,actor.id(),VersionJson.now());n.put("taskDocumentId",caseId).put("status","DRAFT").put("modelId",body.path("modelId").asText()).put("modelVersion",body.path("modelVersion").asText()).put("executionMode",model.path("executionMode").asText()).put("providerVersion",model.path("providerVersion").asText()).put("inputDigest",VersionJson.canonicalHash(frozen)).put("stage","NOT_STARTED").put("progress",0).put("suggestionCount",0).put("reviewAvailability","PENDING_B_CONTRACT");for(String f:List.of("requestedAt","startedAt","completedAt","failureCode","failureMessage"))n.putNull(f);for(String f:List.of("documentTextVersionId","annotationScopeId"))n.set(f,doc.get(f));n.set("guideVersionId",frozen.path("guideVersion").get("id"));store.insert("automationTask",n);var saved=mapper.createObjectNode().put("id",n.path("id").asText());saved.set("input",frozen);store.insert("automationInput",saved);store.event(n,"M02","DRAFT");receipt(actor,operation,key,body,n);return n;
    }
    @Transactional public ObjectNode transition(Actor supplied,String id,String key,int expected,ObjectNode body){var actor=manager(supplied);fields(body,Set.of("action"));require(body.path("action").isTextual()&&Set.of("QUEUE","CANCEL").contains(body.path("action").asText()),ErrorCode.VALIDATION_ERROR,"仅支持排队或取消");VersionJson.uuid(id);VersionJson.uuid(key);var current=read(actor,id);var doc=lockedCase(actor,current.path("taskDocumentId").asText());var n=data.lock("automationTask",id);String operation="M04:"+id;var cached=replay(actor,operation,key,body);if(cached!=null)return cached;writable(doc);require(expected==n.path("recordVersion").asInt(),ErrorCode.VERSION_CONFLICT,"自动任务已变化，请刷新");String action=body.path("action").asText();require(action.equals("QUEUE")?"DRAFT".equals(n.path("status").asText()):Set.of("DRAFT","QUEUED").contains(n.path("status").asText()),ErrorCode.INVALID_AUTO_STATE,"当前状态不可执行此操作；失败或取消后请新建任务");if(action.equals("QUEUE")){enabled(doc);require(baseline(n),ErrorCode.SOURCE_INCOMPLETE,"文本、范围、指南或模型配置已变化，请取消后新建");n.put("status","QUEUED").put("stage","WAITING").put("requestedAt",VersionJson.now());}else n.put("status","CANCELLED").put("stage","CANCELLED").put("completedAt",VersionJson.now());save(n);store.event(n,"M04",n.path("status").asText());receipt(actor,operation,key,body,n);return n;}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public ObjectNode workspace(Actor actor,String status,int page,int size){var result=list(actor,null,status,page,size);var models=result.putArray("models");models.add(adapter.descriptor());result.put("realModelAvailable",false).put("reviewContractReady",false);var options=result.putArray("cases");actor=manager(actor);for(var task:data.find("task",null,null)){if(!actor.id().equals(task.path("ownerUserId").asText())||!task.path("autoPreannotationEnabled").asBoolean())continue;for(var doc:data.find("taskDocument","taskId",task.path("id").asText())){try{ownCase(actor,doc.path("id").asText());writable(doc);}catch(BusinessException e){continue;}var option=options.addObject();option.put("taskDocumentId",doc.path("id").asText()).put("taskName",task.path("name").asText()).put("taskId",task.path("id").asText()).put("title",data.read("document",doc.path("documentId").asText()).path("title").asText()).put("status",doc.path("status").asText());}}return result;}
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public ObjectNode detail(Actor actor,String id){var n=read(actor,id);var result=mapper.createObjectNode();result.set("task",n);var doc=data.read("taskDocument",n.path("taskDocumentId").asText());result.put("taskName",data.read("task",doc.path("taskId").asText()).path("name").asText()).put("documentTitle",data.read("document",doc.path("documentId").asText()).path("title").asText());var candidates=result.putArray("suggestions");data.find("modelSuggestion","automationTaskId",id).forEach(candidates::add);var events=result.putArray("events");data.find("automationEvent","automationTaskId",id).stream().sorted(Comparator.comparingInt(e->e.path("taskRecordVersion").asInt())).forEach(events::add);return result;}
    /** Read-only B integration seam. No M05/M06 public writes or shared review mutation. */
    @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public ObjectNode suggestionsForAssignment(Actor supplied,String assignmentId){var actor=identities.actor(supplied.id());var a=data.read("assignment",VersionJson.uuid(assignmentId));var member=data.read("member",a.path("taskMemberId").asText());var doc=data.read("taskDocument",a.path("taskDocumentId").asText());require(actor.role("ANNOTATOR")&&actor.permission("AUTO_SUGGESTION_REVIEW")&&actor.id().equals(a.path("userId").asText())&&"ACTIVE".equals(a.path("status").asText())&&"ANNOTATOR".equals(a.path("assignmentRole").asText())&&"ACTIVE".equals(member.path("status").asText())&&"ANNOTATOR".equals(member.path("memberRole").asText())&&member.path("userId").equals(a.path("userId"))&&member.path("taskId").equals(doc.path("taskId")),ErrorCode.BLIND_SCOPE_DENIED,"仅本人有效标注分配可读取候选");var result=mapper.createObjectNode().put("reviewContractReady",false);var items=result.putArray("items");for(var n:data.find("automationTask","taskDocumentId",doc.path("id").asText()))if("COMPLETED".equals(n.path("status").asText())&&baseline(n))data.find("modelSuggestion","automationTaskId",n.path("id").asText()).forEach(items::add);return result;}
    public record Job(ObjectNode task,ObjectNode input,String claimId){}
    @Transactional public Job claim(String id){var initial=data.read("automationTask",id);String owner=initial.path("createdById").asText();data.lock("user",owner);versions.lockCase(initial.path("taskDocumentId").asText());var doc=data.lock("taskDocument",initial.path("taskDocumentId").asText());data.lock("task",doc.path("taskId").asText());var n=data.lock("automationTask",id);if(!"QUEUED".equals(n.path("status").asText()))return null;
        ObjectNode frozen;try{var stored=data.read("automationInput",id).path("input");require(stored.isObject()&&VersionJson.canonicalHash(stored).equals(n.path("inputDigest").asText()),ErrorCode.SOURCE_INCOMPLETE,"保存的模型输入摘要不匹配");frozen=((ObjectNode)stored).deepCopy();var actor=manager(identities.actor(owner));ownCase(actor,doc.path("id").asText());writable(doc);enabled(doc);require(baseline(n),ErrorCode.SOURCE_INCOMPLETE,"冻结输入已变化");}catch(BusinessException e){failed(n,"SOURCE_OR_AUTHORIZATION_CHANGED","任务授权、启用状态或冻结输入已变化，未生成候选");return null;}
        String claim=VersionJson.uuid();var run=mapper.createObjectNode().put("id",id).put("claimId",claim).put("expiresAt",Instant.now().plusSeconds(120).truncatedTo(java.time.temporal.ChronoUnit.SECONDS).toString());store.insert("automationRun",run);n.put("status","RUNNING").put("startedAt",VersionJson.now()).put("stage","GENERATING_TEST_CANDIDATES").put("progress",10);save(n);store.event(n,"WORKER_CLAIM","RUNNING");return new Job(n,frozen,claim);
    }
    @Transactional public void finish(Job job,ArrayNode output,boolean adapterFailed){
        var n=lockRun(job);if(n==null)return;ArrayNode candidates;
        try{var actor=manager(identities.actor(n.path("createdById").asText()));var doc=ownCase(actor,n.path("taskDocumentId").asText());writable(doc);enabled(doc);require(baseline(n)&&VersionJson.canonicalHash(job.input()).equals(n.path("inputDigest").asText())&&!adapterFailed,ErrorCode.SOURCE_INCOMPLETE,"执行输入或执行器失败");candidates=validate(n,job.input(),output);}
        catch(BusinessException e){failed(n,adapterFailed?"ADAPTER_FAILED":"INVALID_OUTPUT_OR_SOURCE_CHANGED",adapterFailed?"测试执行器失败，未生成候选；可新建任务重试":"候选校验、授权或冻结输入校验未通过；未发布候选");return;}
        // Publication failures must roll back all candidates and the terminal state, including domain exceptions.
        for(var c:candidates)store.insert("modelSuggestion",(ObjectNode)c);
        n.put("status","COMPLETED").put("stage","AWAITING_HUMAN_REVIEW").put("progress",100).put("suggestionCount",candidates.size()).put("completedAt",VersionJson.now());save(n);store.event(n,"WORKER_COMPLETE","COMPLETED");
    }
    private ObjectNode lockRun(Job job){var initial=data.read("automationTask",job.task().path("id").asText());data.lock("user",initial.path("createdById").asText());versions.lockCase(initial.path("taskDocumentId").asText());var doc=data.lock("taskDocument",initial.path("taskDocumentId").asText());data.lock("task",doc.path("taskId").asText());var n=data.lock("automationTask",initial.path("id").asText());if(!"RUNNING".equals(n.path("status").asText())||!job.claimId().equals(data.read("automationRun",n.path("id").asText()).path("claimId").asText()))return null;if(!Instant.now().isBefore(Instant.parse(data.read("automationRun",n.path("id").asText()).path("expiresAt").asText()))){failed(n,"EXECUTION_INTERRUPTED","执行超时或服务重启中断；未发布候选，请新建任务重试");return null;}return n;}
    @Transactional public void expire(String id){var n=data.read("automationTask",id);if(!"RUNNING".equals(n.path("status").asText()))return;var run=data.read("automationRun",id);if(Instant.now().isBefore(Instant.parse(run.path("expiresAt").asText())))return;lockRun(new Job(n,mapper.createObjectNode(),run.path("claimId").asText()));}
    private ArrayNode validate(ObjectNode task,ObjectNode input,ArrayNode output){require(output!=null&&output.size()<=10000,ErrorCode.VALIDATION_ERROR,"候选数量无效");var valid=mapper.createArrayNode();String text=input.path("text").path("normalizedText").asText();for(var raw:output){require(raw instanceof ObjectNode,ErrorCode.VALIDATION_ERROR,"候选格式无效");fields((ObjectNode)raw,Set.of("suggestionKind","startOffset","endOffset","candidateLabelCode","confidence","participantHints"));require("ELEMENT".equals(raw.path("suggestionKind").asText())&&raw.path("startOffset").isIntegralNumber()&&raw.path("startOffset").canConvertToInt()&&raw.path("endOffset").isIntegralNumber()&&raw.path("endOffset").canConvertToInt()&&raw.path("confidence").isNumber()&&Double.isFinite(raw.path("confidence").asDouble())&&raw.path("confidence").asDouble()>=0&&raw.path("confidence").asDouble()<=1&&raw.path("participantHints").isArray()&&raw.path("participantHints").isEmpty(),ErrorCode.VALIDATION_ERROR,"本执行适配仅允许有效的要素候选");int start=raw.path("startOffset").asInt(),end=raw.path("endOffset").asInt();require(start>=input.path("scope").path("startOffset").asInt()&&end>start&&end<=input.path("scope").path("endOffset").asInt()&&boundary(text,start)&&boundary(text,end),ErrorCode.OFFSET_INVALID,"候选越界或切开 UTF-16 代理对");boolean label=false;for(var l:input.path("labels"))if(l.path("code").equals(raw.path("candidateLabelCode"))&&l.path("enabled").asBoolean(true)&&!Set.of("DISABLED","DELETED").contains(l.path("status").asText()))label=true;require(label,ErrorCode.VALIDATION_ERROR,"候选标签不属于绑定指南");var c=((ObjectNode)raw).deepCopy();VersionJson.stamp(c,task.path("createdById").asText(),VersionJson.now());for(String f:List.of("taskDocumentId","documentTextVersionId","annotationScopeId","modelId","modelVersion","providerVersion","guideVersionId","inputDigest","executionMode"))c.set(f,task.get(f));c.put("automationTaskId",task.path("id").asText()).put("status","PENDING_HUMAN_REVIEW").put("text",text.substring(start,end)).putNull("candidateRelationCode").putNull("targetDraftId").putNull("reviewedById").putNull("reviewedAt");valid.add(c);}return valid;}
    private void failed(ObjectNode n,String code,String message){n.put("status","FAILED").put("stage","FAILED").put("failureCode",code).put("failureMessage",message).put("completedAt",VersionJson.now()).put("suggestionCount",0);save(n);store.event(n,"WORKER_FAILED","FAILED");}
    private void save(ObjectNode n){n.put("recordVersion",n.path("recordVersion").asInt()+1).put("updatedAt",VersionJson.now());data.replace("automationTask",n);}
    private ObjectNode replay(Actor actor,String op,String key,ObjectNode body){return versions.receipt(actor.id(),op,key,VersionJson.canonicalHash(body));}
    private void receipt(Actor actor,String op,String key,ObjectNode body,ObjectNode result){versions.receipt(actor.id(),op,key,VersionJson.canonicalHash(body),result,mapper.createObjectNode(),result,"");}
    public static void fields(ObjectNode body,Set<String> fields){var actual=new HashSet<String>();body.fieldNames().forEachRemaining(actual::add);require(actual.equals(fields),ErrorCode.VALIDATION_ERROR,"请求字段不符合接口约定");}
}
